class Shape {
  String name;
  // parent constructor
  Shape(String name) {
    this.name = name;
    System.out.println("Shape: " + name);
  }
  void info() {
    System.out.println("I am a 2D shape");
  }
}

class Circle extends Shape {
  double r;
  Circle(double r) {
    // 1. call parent ctor FIRST
    super("circle");
    this.r = r;
  }
  void info() {
    // 2. parent's version
    super.info();
    System.out.println("radius = " + r);
  }
}

class Main {
  public static void main(String[] a) {
    Circle c = new Circle(2.5);
    c.info();
  }
}

class Printer {
  // overloading:
  void print(String s) { }
  // different args
  void print(String s, int n) { }

  void header() {
    System.out.println("-- basic --");
  }
}

class LaserPrinter extends Printer {
  // annotation checks it
  @Override
  void header() {
    System.out.println("** LaserJet **");
  }
}

class Main {
  public static void main(String[] a) {
    LaserPrinter hp = new LaserPrinter();
    // overloaded form
    hp.print("A", 5);
    // OVERRIDDEN version runs
    hp.header();
    // the parent's version is replaced
  }
}

class Shape {
  double area() {
    return 0;
  }
}
class Circle extends Shape {
  double r = 5;
  double area() { return 3.14 * r * r; }
}
class Square extends Shape {
  double s = 4;
  double area() { return s * s; }
}

class Main {
  public static void main(String[] a) {
    // parent reference
    Shape sh;
    // holds a Circle
    sh = new Circle();
    double ar = sh.area();
    System.out.println("area = " + ar);
    // now a Square
    sh = new Square();
    ar = sh.area();
    System.out.println("area = " + ar);
    // WHICH area() runs is decided
    // at RUN TIME by the object, not
    // by the reference type.
  }
}

