// abstract class = half-built blueprint
abstract class Shape {
  String type = "shape";

  abstract double area();   // no body
  // -> the child class MUST write it

  // normal method
  void displayType() {
    System.out.println("Type: " + type);
  }
}

class Rectangle extends Shape {
  double l = 12, w = 5;
  Rectangle() { type = "rectangle"; }
  // duty fulfilled
  double area() {
    return l * w;
  }
}

class Main {
  public static void main(String[] a) {
    // ERROR: abstract!
    // Shape s = new Shape();
    Rectangle r = new Rectangle();
    r.displayType();          // inherited
    double ar = r.area();
    System.out.println("area = " + ar);
  }
}

// a pure contract
interface Drawable {
  // auto public abstract
  void draw();
  // auto public static final
  int UNIT = 20;
}

abstract class Shape {
  String type = "shape";
  void displayType() { }
}

class Circle extends Shape
    // both together
    implements Drawable {
  // must be public!
  public void draw() {
    System.out.println("O  (circle)");
  }
}

class Rectangle extends Shape
    implements Drawable {
  public void draw() {
    System.out.println("[ ] (rectangle)");
  }
}

class Main {
  public static void main(String[] a) {
    Drawable d1 = new Circle();
    d1.draw();
    Drawable d2 = new Rectangle();
    d2.draw();
    int u = Drawable.UNIT;
    System.out.println("UNIT = " + u);
  }
}

interface Printable {
  void print();
}
interface Showable {
  void show();
}

class Report implements Printable,
    Showable {
  public void print() {
    System.out.println("printing...");
  }
  public void show() {
    System.out.println("showing...");
  }
}

class Main {
  public static void main(String[] a) {
    Report r = new Report();
    r.print();
    r.show();
  }
}

interface ShapeMath {
  // abstract
  double area();

  // ready-made
  default String desc() {
    return "I have area " + area();
  }
  // called on the interface
  static String banner() {
    return "== shape maths ==";
  }
}

class Square implements ShapeMath {
  double s = 4;
  public double area() { return s * s; }
  // desc() inherited for free
}

class Main {
  public static void main(String[] a) {
    Square q = new Square();
    System.out.println(ShapeMath.banner());
    System.out.println(q.desc());
  }
}

